import { writeFileSync } from 'node:fs';
import { resolve } from 'node:path';

const outputPath = resolve(process.argv[2] || 'server/.env.production');

const required = [
    'GITHUB_REPOSITORY',
    'IMAGE_TAG',
    'MYSQL_ROOT_PASSWORD',
    'BASE_URL',
    'API_DOMAIN',
    'JWT_SECRET',
    'ADMIN_EMAIL',
    'ADMIN_PASSWORD',
    'ADMIN_COOKIE_SECRET',
    'WECHAT_APPID',
    'WECHAT_SECRET',
    'AI_API_KEY',
    'AI_API_URL',
    'AI_MODEL'
];

const missing = required.filter((name) => !process.env[name]?.trim());
if (missing.length) {
    throw new Error(`Missing required production secrets: ${missing.join(', ')}`);
}

const values = {
    GITHUB_REPOSITORY: process.env.GITHUB_REPOSITORY.toLowerCase(),
    IMAGE_TAG: process.env.IMAGE_TAG,
    MYSQL_ROOT_PASSWORD: process.env.MYSQL_ROOT_PASSWORD,
    DATABASE_URL: `mysql://root:${encodeURIComponent(process.env.MYSQL_ROOT_PASSWORD)}@mysql:3306/drim`,
    BASE_URL: process.env.BASE_URL,
    API_DOMAIN: process.env.API_DOMAIN,
    JWT_SECRET: process.env.JWT_SECRET,
    JWT_EXPIRES_IN: process.env.JWT_EXPIRES_IN || '7d',
    ADMIN_EMAIL: process.env.ADMIN_EMAIL,
    ADMIN_PASSWORD: process.env.ADMIN_PASSWORD,
    ADMIN_COOKIE_SECRET: process.env.ADMIN_COOKIE_SECRET,
    WECHAT_APPID: process.env.WECHAT_APPID,
    WECHAT_SECRET: process.env.WECHAT_SECRET,
    WECHAT_REMINDER_TEMPLATE_ID: process.env.WECHAT_REMINDER_TEMPLATE_ID || '',
    AI_API_KEY: process.env.AI_API_KEY,
    AI_API_URL: process.env.AI_API_URL,
    AI_MODEL: process.env.AI_MODEL,
    AI_API_FORMAT: process.env.AI_API_FORMAT || 'openai',
    AI_SYSTEM_PROMPT: process.env.AI_SYSTEM_PROMPT || '你是一个专业的梦境解析师，擅长心理学和传统解梦文化。',
    CONTENT_SECURITY_SKIP: process.env.CONTENT_SECURITY_SKIP || 'false',
    CONTENT_SECURITY_FAIL_SAFE: process.env.CONTENT_SECURITY_FAIL_SAFE || 'true'
};

if (values.ADMIN_PASSWORD.length < 12) {
    throw new Error('ADMIN_PASSWORD must contain at least 12 characters');
}
if (values.ADMIN_COOKIE_SECRET.length < 32) {
    throw new Error('ADMIN_COOKIE_SECRET must contain at least 32 characters');
}
if (!['openai', 'dashscope', 'anthropic'].includes(values.AI_API_FORMAT)) {
    throw new Error('AI_API_FORMAT must be openai, dashscope or anthropic');
}
if (!/^[a-z0-9.-]+(?::[0-9]+)?$/.test(values.API_DOMAIN)) {
    throw new Error('API_DOMAIN must be a hostname without a URL scheme or path');
}
if (!/^[0-9a-f]{40}$/.test(values.IMAGE_TAG)) {
    throw new Error('IMAGE_TAG must be a full Git commit SHA');
}
if (!/^[a-z0-9_.-]+\/[a-z0-9_.-]+$/.test(values.GITHUB_REPOSITORY)) {
    throw new Error('GITHUB_REPOSITORY must use the owner/repository format');
}

const quote = (name, value) => {
    if (/[\r\n\0]/.test(value)) {
        throw new Error(`${name} must be a single-line value`);
    }
    // Compose treats single-quoted values literally; only a single quote needs escaping.
    return `'${value.replaceAll("'", "\\'")}'`;
};

const content = [
    '# Generated by GitHub Actions. Do not edit on the server.',
    ...Object.entries(values).map(([name, value]) => `${name}=${quote(name, value)}`),
    ''
].join('\n');

writeFileSync(outputPath, content, { encoding: 'utf8', mode: 0o600 });
console.log(`Generated ${outputPath} with ${Object.keys(values).length} validated variables`);
